    { const char * tb_v3365 = "            } else {           // свои коды в начале блока\n"; *(const char * *)tb_grow(v_lines) = tb_v3365; }
    { const char * tb_v3366 = "                nl = (int)tb_zbits(z, 5) + 257; nd = (int)tb_zbits(z, 5) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3366; }
    { const char * tb_v3367 = "                int nc = (int)tb_zbits(z, 4) + 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v3367; }
    { const char * tb_v3368 = "                unsigned char cl[19] = { 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3368; }
    { const char * tb_v3369 = "                for (int i = 0; i < nc; i++) cl[order[i]] = (unsigned char)tb_zbits(z, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v3369; }
    { const char * tb_v3370 = "                tb_huff ch; tb_hbuild(&ch, cl, 19);\n"; *(const char * *)tb_grow(v_lines) = tb_v3370; }
    { const char * tb_v3371 = "                int i = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3371; }
