    { const char * tb_v3639 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3639; }
    { const char * tb_v3640 = "// ---------- Vulkan (Linux и Windows) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3640; }
    { const char * tb_v3641 = "// Свои описания Vulkan (только то, что нужно): программе не нужны заголовки Vulkan,\n"; *(const char * *)tb_grow(v_lines) = tb_v3641; }
    { const char * tb_v3642 = "// а сама библиотека Vulkan грузится при запуске (dlopen) — нет её, рисуем на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v3642; }
