    { const char * tb_v4976 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4976; }
    { const char * tb_v4977 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4977; }
    { const char * tb_v4978 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4978; }
    { const char * tb_v4979 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4979; }
    { const char * tb_v4980 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4980; }
    { const char * tb_v4981 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4981; }
    { const char * tb_v4982 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4982; }
